using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using Codice.Characters;using Codice.Bosses;using Codice.Expedition;using Codice.Mechanics;using Codice.Presentation;using Codice.UI;
public static class VerifyAudioEnding {
 static void Assert(bool b,string message){if(!b)throw new Exception(message);}
 static void Set(object target,string name,object value)=>target.GetType().GetField("<"+name+">k__BackingField",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(target,value);
 public static string Assets(){var a=Resources.Load<GameAudioLibrary>("GameAudioLibrary");foreach(SoundCue cue in Enum.GetValues(typeof(SoundCue))){var entries=a.effects.Where(e=>e.cue==cue).ToArray();Assert(entries.Length==1&&entries[0].clips.All(c=>c&&c.length>0),"Missing/duplicate "+cue);}Assert(a.bossTension&&a.ending,"Missing loops");return "PASS "+a.effects.Length+" unique cues, clips and adaptive tracks";}
 public static string Load(){PlayerPrefs.SetInt("Cinders.TestEnding.Dawn",PlayerPrefs.GetInt("Cinders.Ending.Dawn",0));PlayerPrefs.SetInt("Cinders.TestEnding.Vigil",PlayerPrefs.GetInt("Cinders.Ending.Vigil",0));MainMenuUI.UnlockCheats("jam");ExpeditionFloor.DebugSeed=8137;RunNavigation.StartExpeditionTest(PlayerClass.Warrior,15);return "Loading 5-3";}
 public static string Start(){var r=RunDirector.Instance;r.Player.State.LaboratoryImmortal=true;Assert(GameAudio.Instance.CurrentMusic==GameAudio.Instance.Library.dungeon,"Exploration music absent");JamDebug.Teleport(r.Expedition.Layout.Boss);return "Entered final boss";}
 public static async Task<string> Phases(){var r=RunDirector.Instance;var b=r.Expedition.context.arena.ActiveBoss;var a=GameAudio.Instance;Assert(b,"Boss missing");Assert(a.CurrentMusic==a.Library.arena,"Combat track absent");int phase=a.Count(SoundCue.BossPhase),low=a.Count(SoundCue.BossLow);b.ReceiveDamage(new DamageInfo{amount=b.MaxHealth*.4f,source=r.Player.gameObject,ignoreGuard=true});await Task.Delay(300);Assert(a.Count(SoundCue.BossPhase)==phase+1,"65% cue");b.ReceiveDamage(new DamageInfo{amount=b.MaxHealth*.35f,source=r.Player.gameObject,ignoreGuard=true});await Task.Delay(700);Assert(a.Count(SoundCue.BossLow)==low+1&&a.BossTensionActive,"30% cue/tension");b.ReceiveDamage(new DamageInfo{amount=1,source=r.Player.gameObject,ignoreGuard=true});await Task.Delay(300);Assert(a.Count(SoundCue.BossLow)==low+1,"Low cue repeats");int death=a.Count(SoundCue.BossDeath);b.ReceiveDamage(new DamageInfo{amount=100000,source=r.Player.gameObject,ignoreGuard=true});await Task.Delay(400);Assert(a.Count(SoundCue.BossDeath)==death+1,"Death sound absent");Assert(r.Phase==RunPhase.Cleared&&UnityEngine.Object.FindAnyObjectByType<FinalSanctum>(),"No final entrance");Assert(!r.FinishDescent(true),"Missing requirements accepted");return "PASS adaptive music, thresholds once, death cue, final gate and unmet requirements";}
 public static async Task<string> Open(){var r=RunDirector.Instance;Set(r,"DestinyOrbs",7);Set(r,"LastBellSeal",true);var gate=UnityEngine.Object.FindAnyObjectByType<FinalSanctum>();var cc=r.Player.GetComponent<CharacterController>();cc.enabled=false;r.Player.transform.position=gate.transform.position-Vector3.forward*2;cc.enabled=true;gate.Interact(r.Player);await Task.Delay(2100);Assert(gate.Opened,"Gate does not open");var heart=UnityEngine.Object.FindObjectsByType<EndingChoice>().First(c=>c.release);cc.enabled=false;r.Player.transform.position=heart.transform.position-Vector3.forward*1.5f;cc.enabled=true;heart.Interact(r.Player);Assert(r.Phase==RunPhase.Victory&&r.EndingTitle=="EL ALBA SIN DEUDA","True ending");return "PASS physical door opens and heart concludes true ending";}
 public static string Ordinary(){var r=RunDirector.Instance;r.SetExpeditionPhase(RunPhase.Cleared,"test");Set(r,"DestinyOrbs",0);Set(r,"LastBellSeal",false);var m=UnityEngine.Object.FindObjectsByType<EndingChoice>().First(c=>!c.release);var cc=r.Player.GetComponent<CharacterController>();cc.enabled=false;r.Player.transform.position=m.transform.position-Vector3.forward;cc.enabled=true;m.Interact(r.Player);Assert(r.Phase==RunPhase.Cleared,"No confirmation");m.Interact(r.Player);Assert(r.Phase==RunPhase.Victory&&r.EndingTitle=="EL ÚLTIMO VIGÍA","Ordinary ending");return "PASS alternative ending without keys, two-step confirmation";}
 public static string Progress(){var r=RunDirector.Instance;Set(r,"DestinyOrbs",0);Set(r,"LastBellSeal",false);foreach(int f in new[]{3,6,9}){Set(r,"FloorNumber",f);r.CollectDestinyOrb();}Set(r,"FloorNumber",12);r.RecoverBellSeal();Assert(r.TrueEndingReady,"Progress collection");Set(r,"FloorNumber",15);return "PASS three distinct orbs plus fourth-world seal";}
 public static string Restore(){foreach(string k in new[]{"Dawn","Vigil"}){PlayerPrefs.SetInt("Cinders.Ending."+k,PlayerPrefs.GetInt("Cinders.TestEnding."+k,0));PlayerPrefs.DeleteKey("Cinders.TestEnding."+k);}PlayerPrefs.Save();return "Test achievements restored";}
}
